screenPanels.initJs:
function(container, apiUrl, tables) {
  // テーブルインデックス
  const USERS_IDX = 0;
  const ACTIVITIES_IDX = 1;
  const CUSTOMERS_IDX = 2;
  const CONTRACTS_IDX = 3;

  // DOM要素
  const periodStartInput = container.querySelector('[data-testid="period-start"]');
  const periodEndInput = container.querySelector('[data-testid="period-end"]');
  const userSelect = container.querySelector('[data-testid="user-select"]');
  const customerStatusSelect = container.querySelector('[data-testid="customer-status"]');
  const metricCheckboxes = {
    contracts: container.querySelector('[data-testid="metric-contracts"]'),
    revenue: container.querySelector('[data-testid="metric-revenue"]'),
    avgRevenue: container.querySelector('[data-testid="metric-avg-revenue"]'),
    activities: container.querySelector('[data-testid="metric-activities"]')
  };
  const executeBtn = container.querySelector('[data-testid="execute-aggregation"]');
  const progressSection = container.querySelector('#progress-section');
  const progressBar = container.querySelector('#progress-bar');
  const progressText = container.querySelector('#progress-text');
  const resultKpi = container.querySelector('#result-kpi');
  const resultDetail = container.querySelector('#result-detail');
  const resultEmpty = container.querySelector('#result-empty');
  const resultActions = container.querySelector('#result-actions');
  const resultTbody = container.querySelector('#result-tbody');
  const generateReportBtn = container.querySelector('[data-testid="generate-report"]');
  const exportCsvBtn = container.querySelector('[data-testid="export-csv"]');

  // 初期化：デフォルト日付を設定
  const today = new Date();
  const firstDay = new Date(today.getFullYear(), today.getMonth(), 1);
  periodStartInput.valueAsDate = firstDay;
  periodEndInput.valueAsDate = today;

  // ユーザー一覧を取得してセレクトに追加
  async function loadUsers() {
    const users = await window.aivicApi.list(USERS_IDX);
    if (users && users.length > 0) {
      users.forEach(user => {
        const option = document.createElement('option');
        option.value = user.id || user.ユーザーID;
        option.textContent = user.ユーザー名 || user.name || 'Unknown';
        userSelect.appendChild(option);
      });
    }
  }

  // 集計実行
  executeBtn.addEventListener('click', async () => {
    const startDate = periodStartInput.valueAsDate;
    const endDate = periodEndInput.valueAsDate;
    const userId = userSelect.value;
    const customerStatus = customerStatusSelect.value;

    if (!startDate || !endDate) {
      alert('集計期間を指定してください');
      return;
    }

    // 進捗表示
    progressSection.style.display = 'block';
    resultKpi.style.display = 'none';
    resultDetail.style.display = 'none';
    resultEmpty.style.display = 'none';
    resultActions.style.display = 'none';

    // シミュレーション進捗
    let progress = 0;
    const progressInterval = setInterval(() => {
      progress += Math.random() * 30;
      if (progress > 90) progress = 90;
      progressBar.style.width = progress + '%';
      progressText.textContent = Math.floor(progress) + '%';
    }, 200);

    try {
      // データ取得
      const activities = await window.aivicApi.list(ACTIVITIES_IDX);
      const contracts = await window.aivicApi.list(CONTRACTS_IDX);
      const customers = await window.aivicApi.list(CUSTOMERS_IDX);

      // フィルタリング
      const filteredActivities = (activities || []).filter(a => {
        const actDate = new Date(a.活動日 || a.activityDate);
        const isInRange = actDate >= startDate && actDate <= endDate;
        const isUser = !userId || (a.ユーザーID === userId || a.userId === userId);
        return isInRange && isUser;
      });

      const filteredContracts = (contracts || []).filter(c => {
        const contractDate = new Date(c.成約日 || c.contractDate);
        const isInRange = contractDate >= startDate && contractDate <= endDate;
        const isUser = !userId || (c.ユーザーID === userId || c.userId === userId);
        let isStatus = true;
        if (customerStatus && customers) {
          const customer = customers.find(cust => cust.顧客企業ID === c.顧客企業ID || cust.id === c.customerId);
          isStatus = customer && (customer.ステータス === customerStatus || customer.status === customerStatus);
        }
        return isInRange && isUser && isStatus;
      });

      // 集計計算
      const contractCount = filteredContracts.length;
      const totalRevenue = filteredContracts.reduce((sum, c) => sum + (c.成約金額 || c.contractAmount || 0), 0);
      const avgRevenue = contractCount > 0 ? Math.floor(totalRevenue / contractCount) : 0;
      const activityCount = filteredActivities.length;

      // ユーザー別集計
      const userAggregation = {};
      filteredContracts.forEach(c => {
        const uid = c.ユーザーID || c.userId;
        if (!userAggregation[uid]) {
          userAggregation[uid] = { contracts: 0, revenue: 0, activities: 0, userName: '' };
        }
        userAggregation[uid].contracts++;
        userAggregation[uid].revenue += c.成約金額 || c.contractAmount || 0;
      });

      filteredActivities.forEach(a => {
        const uid = a.ユーザーID || a.userId;
        if (!userAggregation[uid]) {
          userAggregation[uid] = { contracts: 0, revenue: 0, activities: 0, userName: '' };
        }
        userAggregation[uid].activities++;
      });

      // ユーザー名を取得
      const users = await window.aivicApi.list(USERS_IDX);
      Object.keys(userAggregation).forEach(uid => {
        const user = users.find(u => u.id === uid || u.ユーザーID === uid);
        userAggregation[uid].userName = user ? (user.ユーザー名 || user.name || 'Unknown') : 'Unknown';
      });

      // 進捗完了
      clearInterval(progressInterval);
      progressBar.style.width = '100%';
      progressText.textContent = '100%';

      // 結果表示
      setTimeout(() => {
        progressSection.style.display = 'none';
        resultEmpty.style.display = 'none';

        // KPI表示
        if (metricCheckboxes.contracts.checked || metricCheckboxes.revenue.checked || 
            metricCheckboxes.avgRevenue.checked || metricCheckboxes.activities.checked) {
          resultKpi.style.display = 'grid';
          container.querySelector('[data-testid="kpi-contracts"]').textContent = contractCount;
          container.querySelector('[data-testid="kpi-revenue"]').textContent = '¥' + totalRevenue.toLocaleString('ja-JP');
          container.querySelector('[data-testid="kpi-avg-revenue"]').textContent = '¥' + avgRevenue.toLocaleString('ja-JP');
          container.querySelector('[data-testid="kpi-activities"]').textContent = activityCount;
        }

        // 詳細テーブル
        resultTbody.innerHTML = '';
        Object.entries(userAggregation).forEach(([uid, data]) => {
          const row = document.createElement('tr');
          row.style.borderBottom = '1px solid var(--border)';
          row.innerHTML = `
            <td style="padding: 6px 4px; color: var(--text);">${data.userName}</td>
            <td style="text-align: right; padding: 6px 4px; color: var(--text);">${data.contracts}</td>
            <td style="text-align: right; padding: 6px 4px; color: var(--text);">¥${data.revenue.toLocaleString('ja-JP')}</td>
            <td style="text-align: right; padding: 6px 4px; color: var(--text);">${data.activities}</td>
          `;
          resultTbody.appendChild(row);
        });

        resultDetail.style.display = 'flex';
        resultActions.style.display = 'flex';

        // 集計結果をグローバルに保存（レポート生成時に使用）
        window.aggregationResult = {
          startDate, endDate, userId, customerStatus,
          contractCount, totalRevenue, avgRevenue, activityCount,
          userAggregation
        };
      }, 500);
    } catch (error) {
      clearInterval(progressInterval);
      progressSection.style.display = 'none';
      alert('集計処理中にエラーが発生しました: ' + (error.message || 'Unknown error'));
    }
  });

  // レポート生成へ遷移
  generateReportBtn.addEventListener('click', () => {
    window.showScreen('scr-1782622862824'); // レポート自動生成・配信画面
  });

  // CSVエクスポート
  exportCsvBtn.addEventListener('click', () => {
    if (!window.aggregationResult) {
      alert('集計結果がありません');
      return;
    }

    const { userAggregation, startDate, endDate } = window.aggregationResult;
    const headers = ['営業担当者', '成約件数', '成約金額', '営業活動件数'];
    const rows = Object.values(userAggregation).map(data => [
      data.userName,
      data.contracts,
      data.revenue,
      data.activities
    ]);

    // CSV生成
    const bom = '\uFEFF';
    const csvContent = bom + headers.join(',') + '\n' + rows.map(r => r.join(',')).join('\n');
    const blob = new Blob([csvContent], { type: 'text/csv;charset=utf-8;' });
    const link = document.createElement('a');
    link.href = URL.createObjectURL(blob);
    link.download = `aggregation_${startDate.toISOString().split('T')[0]}_to_${endDate.toISOString().split('T')[0]}.csv`;
    link.click();
  });

  // 初期化
  loadUsers();
}

function(container, apiUrl, tables) {
  const reportTable = tables[0]; // 生成済みレポート
  const deliveryHistoryTable = tables[1]; // レポート配信履歴
  const userTable = tables[2]; // ユーザー

  let allReports = [];
  let selectedReportId = null;

  // ステータスバッジの色分け
  function getStatusBadgeStyle(status) {
    const baseStyle = "padding: 3px 8px; border-radius: 3px; font-size: 11px; font-weight: 500;";
    if (status === "配信済み") return baseStyle + " background: rgba(76, 175, 80, 0.2); color: #4caf50;";
    if (status === "未配信") return baseStyle + " background: rgba(255, 193, 7, 0.2); color: #ffc107;";
    if (status === "配信失敗") return baseStyle + " background: rgba(244, 67, 54, 0.2); color: #f44336;";
    return baseStyle + " background: var(--border); color: var(--text-muted);";
  }

  // レポート一覧を取得・表示
  async function loadReports() {
    const reports = await window.aivicApi.list(0);
    if (!reports) return;
    allReports = reports;
    renderReportList(reports);
  }

  // レポート一覧をレンダリング
  function renderReportList(reports) {
    const tbody = container.querySelector("[data-testid='report-tbody']");
    tbody.innerHTML = "";
    reports.forEach(report => {
      const row = document.createElement("tr");
      row.dataset.id = report.id;
      row.style.cssText = "cursor: pointer; border-bottom: 1px solid var(--border); transition: background 0.2s;";
      row.onmouseover = () => row.style.background = "rgba(212, 175, 55, 0.08)";
      row.onmouseout = () => row.style.background = "";
      row.onclick = () => selectReport(report.id);

      const genDate = new Date(report.生成日時).toLocaleString('ja-JP', { year: 'numeric', month: '2-digit', day: '2-digit', hour: '2-digit', minute: '2-digit' });
      const salesperson = report.ユーザーID ? `営業${report.ユーザーID.slice(0, 4)}` : "不明";
      const revenue = report.売上金額 ? `¥${(report.売上金額).toLocaleString()}` : "¥0";

      row.innerHTML = `
        <td style="padding: 6px 8px; border-right: 1px solid var(--border); color: var(--text);">${genDate}</td>
        <td style="padding: 6px 8px; border-right: 1px solid var(--border); color: var(--text);">${salesperson}</td>
        <td style="padding: 6px 8px; border-right: 1px solid var(--border);"><span style="${getStatusBadgeStyle(report.配信ステータス)}">${report.配信ステータス}</span></td>
        <td style="padding: 6px 8px; text-align: center; color: var(--primary); font-weight: 500;">${revenue}</td>
      `;
      tbody.appendChild(row);
    });
  }

  // レポート選択時の処理
  function selectReport(reportId) {
    selectedReportId = reportId;
    const report = allReports.find(r => r.id === reportId);
    if (!report) return;

    // 詳細表示
    const detailHeader = container.querySelector("#detail-header");
    const detailEmpty = container.querySelector("#detail-empty");
    const contentPreview = container.querySelector("#content-preview");
    const contentEmpty = container.querySelector("#content-empty");

    detailHeader.style.display = "block";
    detailEmpty.style.display = "none";
    contentPreview.style.display = "block";
    contentEmpty.style.display = "none";

    // 詳細情報を埋める
    container.querySelector("#detail-title").textContent = report.レポートタイトル || "レポート";
    const startDate = new Date(report.レポート期間開始日).toLocaleDateString('ja-JP');
    const endDate = new Date(report.レポート期間終了日).toLocaleDateString('ja-JP');
    container.querySelector("#detail-period").textContent = `${startDate} ～ ${endDate}`;

    const badge = container.querySelector("#detail-status-badge");
    badge.style.cssText = getStatusBadgeStyle(report.配信ステータス);
    badge.textContent = report.配信ステータス;

    container.querySelector("#detail-revenue").textContent = `¥${(report.売上金額 || 0).toLocaleString()}`;
    container.querySelector("#detail-contracts").textContent = `${report.成約件数 || 0}件`;
    const achievement = report.成約件数 > 0 ? Math.round((report.売上金額 / (report.成約件数 * 1000000)) * 100) : 0;
    container.querySelector("#detail-achievement").textContent = `${achievement}%`;

    container.querySelector("#content-text").textContent = report.レポート内容 || "内容なし";

    // アクションボタン表示
    container.querySelector("[data-testid='detail-button']").style.display = "block";
    container.querySelector("[data-testid='delivery-button']").style.display = "block";
    container.querySelector("[data-testid='history-button']").style.display = "block";
    container.querySelector("[data-testid='regenerate-button']").style.display = "block";

    // 配信履歴を表示
    loadDeliveryHistory(reportId);
  }

  // 配信履歴を表示
  async function loadDeliveryHistory(reportId) {
    const histories = await window.aivicApi.list(1);
    if (!histories) return;

    const filtered = histories.filter(h => h.生成済みレポートID === reportId);
    const historyDiv = container.querySelector("#delivery-history");

    if (filtered.length === 0) {
      historyDiv.innerHTML = '<div style="text-align: center; color: var(--text-muted);">配信履歴なし</div>';
      return;
    }

    historyDiv.innerHTML = filtered.map(h => {
      const deliveryDate = new Date(h.配信日時).toLocaleString('ja-JP', { year: 'numeric', month: '2-digit', day: '2-digit', hour: '2-digit', minute: '2-digit' });
      const statusColor = h.配信ステータス === "成功" ? "#4caf50" : h.配信ステータス === "失敗" ? "#f44336" : "#ffc107";
      return `
        <div style="padding: 6px; border-left: 3px solid ${statusColor}; background: rgba(212, 175, 55, 0.05); border-radius: 2px;">
          <div style="display: flex; justify-content: space-between; align-items: center; margin-bottom: 2px;">
            <span style="font-weight: 500; color: var(--text);">${h.配信先メールアドレス}</span>
            <span style="color: ${statusColor}; font-weight: 500;">${h.配信ステータス}</span>
          </div>
          <div style="color: var(--text-muted); font-size: 10px;">${deliveryDate}</div>
          ${h.エラーメッセージ ? `<div style="color: #f44336; font-size: 10px; margin-top: 2px;">${h.エラーメッセージ}</div>` : ""}
        </div>
      `;
    }).join("");
  }

  // 検索フィルター
  container.querySelector("[data-testid='search-button']").onclick = async () => {
    const salesperson = container.querySelector("[data-testid='salesperson-filter']").value;
    const status = container.querySelector("[data-testid='delivery-status-filter']").value;
    const startDate = container.querySelector("[data-testid='period-start-filter']").value;
    const endDate = container.querySelector("[data-testid='period-end-filter']").value;

    let filtered = allReports;
    if (salesperson) filtered = filtered.filter(r => r.ユーザーID === salesperson);
    if (status) filtered = filtered.filter(r => r.配信ステータス === status);
    if (startDate) filtered = filtered.filter(r => new Date(r.生成日時) >= new Date(startDate));
    if (endDate) filtered = filtered.filter(r => new Date(r.生成日時) <= new Date(endDate));

    renderReportList(filtered);
  };

  // 配信ボタン
  container.querySelector("[data-testid='delivery-button']").onclick = () => {
    const modal = container.querySelector("#delivery-modal");
    modal.style.display = "flex";
  };

  // 配信モーダル閉じる
  container.querySelector("#delivery-cancel").onclick = () => {
    container.querySelector("#delivery-modal").style.display = "none";
  };
  container.querySelector("#delivery-modal").onclick = (e) => {
    if (e.target === container.querySelector("#delivery-modal")) {
      container.querySelector("#delivery-modal").style.display = "none";
    }
  };

  // 配信実行
  container.querySelector("#delivery-confirm").onclick = async () => {
    const email = container.querySelector("#delivery-email").value;
    const method = container.querySelector("#delivery-method").value;
    if (!email) {
      alert("メールアドレスを入力してください");
      return;
    }
    // 配信履歴を保存
    await window.aivicApi.save(1, {
      生成済みレポートID: selectedReportId,
      配信先ユーザーID: "system",
      配信先メールアドレス: email,
      配信日時: new Date().toISOString(),
      配信ステータス: "成功",
      配信方法: method,
      開封フラグ: false,
      再配信フラグ: false,
      再配信回数: 0
    });
    container.querySelector("#delivery-modal").style.display = "none";
    loadReports();
  };

  // 再生成ボタン
  container.querySelector("[data-testid='regenerate-button']").onclick = () => {
    container.querySelector("#regenerate-modal").style.display = "flex";
  };

  // 再生成モーダル閉じる
  container.querySelector("#regenerate-cancel").onclick = () => {
    container.querySelector("#regenerate-modal").style.display = "none";
  };
  container.querySelector("#regenerate-modal").onclick = (e) => {
    if (e.target === container.querySelector("#regenerate-modal")) {
      container.querySelector("#regenerate-modal").style.display = "none";
    }
  };

  // 再生成実行
  container.querySelector("#regenerate-confirm").onclick = async () => {
    const report = allReports.find(r => r.id === selectedReportId);
    if (!report) return;
    // レポートを再生成（ここでは更新日時を更新）
    await window.aivicApi.update(0, selectedReportId, {
      生成日時: new Date().toISOString(),
      配信ステータス: "未配信"
    });
    container.querySelector("#regenerate-modal").style.display = "none";
    loadReports();
  };

  // テンプレート管理へ遷移
  container.querySelector("[data-testid='template-mgmt-btn']").onclick = () => {
    window.showScreen("scr-1782622835730");
  };

  // 自動生成・配信へ遷移
  container.querySelector("[data-testid='auto-generate-btn']").onclick = () => {
    window.showScreen("scr-1782622862824");
  };

  // 詳細表示ボタン
  container.querySelector("[data-testid='detail-button']").onclick = () => {
    window.showScreen("scr-1782622876283");
  };

  // 配信履歴確認ボタン
  container.querySelector("[data-testid='history-button']").onclick = () => {
    alert("配信履歴: 下部のタイムラインを参照してください");
  };

  // 初期ロード
  loadReports();
}
